use std::convert::TryInto;use std::fs::{File,metadata};use std::io::{BufReader,Read};
const P:&str="computations/unaudited-codex-orbit0-k15-k3-full-export-plan-2026-08-23/checkpoint_k15_k3_profiles_merged.bin";const H:usize=128;const R:usize=104;const U:i128=400_591_699_200;
fn u16le(x:&[u8])->u16{u16::from_le_bytes(x.try_into().unwrap())}fn u32le(x:&[u8])->u32{u32::from_le_bytes(x.try_into().unwrap())}fn u64le(x:&[u8])->u64{u64::from_le_bytes(x.try_into().unwrap())}fn i128le(x:&[u8])->i128{i128::from_le_bytes(x.try_into().unwrap())}
fn main(){let mut r=BufReader::with_capacity(1<<20,File::open(P).unwrap());let mut h=[0u8;H];r.read_exact(&mut h).unwrap();assert_eq!(&h[..8],b"K15MRG1\0");assert_eq!(u32le(&h[8..12]),1);assert_eq!(u16le(&h[12..14])as usize,R);assert_eq!(i128le(&h[16..32]),U);let parts=u64le(&h[32..40]);let input_records=u64le(&h[40..48]);let input_uses=u64le(&h[48..56]);let n=u64le(&h[56..64]);let zeros=u64le(&h[64..72]);let expected_uses=u64le(&h[72..80]);let input_weight=i128le(&h[80..96]);let expected_weight=i128le(&h[96..112]);let source_uses=u64le(&h[112..120]);let zero_uses=u64le(&h[120..128]);assert_eq!((parts,input_records,input_uses,source_uses),(485,202_344_547,2_358_046_720,2_358_046_720));assert_eq!((n,zeros,expected_uses,zero_uses),(25_564_391,1_411_149,2_311_887_188,46_159_532));assert_eq!(input_weight,expected_weight);assert_eq!(metadata(P).unwrap().len(),H as u64+R as u64*n);let(mut prior,mut uses,mut weight)=(None,0u64,0i128);for _ in 0..n{let mut x=[0u8;R];r.read_exact(&mut x).unwrap();let mut k=[0u8;42];k.copy_from_slice(&x[..42]);if let Some(p)=prior{assert!(p<k)}prior=Some(k);let w=i128le(&x[42..58]);let u=u64le(&x[58..66]);assert_ne!(w,0);assert!(u>0);assert_eq!(x[100],x[41]);let m1=x[101]as i128;let m2=x[102]as i128;assert!(m1>0&&m2>0&&U%(m1*m2)==0);assert!(x[103]<3);uses+=u;weight+=w}let mut tail=[0u8;1];assert_eq!(r.read(&mut tail).unwrap(),0);assert_eq!((uses,weight),(expected_uses,expected_weight));assert_eq!(uses+zero_uses,input_uses);println!("PASS parts={} input_records={} output_records={} zero_groups={} output_uses={} zero_uses={} weight={} bytes={}",parts,input_records,n,zeros,uses,zero_uses,weight,metadata(P).unwrap().len())}
